-- The POST /game/list main statement exactly as it stood before ONEAPI-529.
-- Pinned here so the rewrite can be diffed against it on a live dataset; the test
-- reads the replacement out of the @Query annotation, so only this side is frozen.
-- Named parameters are left in place and bound by the test.
SELECT gamelist.gameCode, IFNULL(languageList.langName, gamelist.GameName) AS name, gamelist.categoryCode, IFNULL( concat(:gameUrl, (IFNULL(languageList.langImageSquare, gamelist.defaultImageSquare))), null) AS imageSquare, IFNULL( concat( :gameUrl, (IFNULL(languageList.langImageLandscape, gamelist.defaultImageLanscape))), null) AS imageLanscape, gamelist.languageCode, gamelist.platformCode, gamelist.currencyCode FROM (SELECT vg.id AS gameID, vg.code AS gameCode, vg.name as GameName, vg.image_square AS defaultImageSquare, vg.image_landscape AS defaultImageLanscape, vgc.status, gc.code AS categoryCode, v.code AS vendorCode, GROUP_CONCAT(DISTINCT l.code SEPARATOR ',') AS languageCode, GROUP_CONCAT(DISTINCT p.code SEPARATOR ',') AS platformCode, GROUP_CONCAT(DISTINCT c.code SEPARATOR ',') AS currencyCode FROM vendor_game_codes AS vgc INNER JOIN vendor_games vg ON vgc.vendor_game_id = vg.id INNER JOIN languages l on l.id = vgc.language_id  INNER JOIN platforms p on p.id = vgc.platform_id INNER JOIN game_categories gc on vg.game_category_id = gc.id INNER JOIN vendors v on vg.vendor_id = v.id INNER JOIN vendor_game_currencies vgcurrency on vg.id = vgcurrency.vendor_game_id INNER JOIN currencies c on c.id = vgcurrency.currency_id WHERE  vgc.vendor_game_id not IN (    SELECT vendor_game_id FROM vendor_game_deactivated as game_deactived    INNER JOIN vendor_games  on game_deactived.vendor_game_id = vendor_games.id    WHERE   vendor_games.vendor_id = :vendorId AND    ((game_deactived.sas_entity_hierarchy_id =1) OR    (game_deactived.sas_entity_hierarchy_id =2 AND game_deactived.house_id = :houseId) OR    (game_deactived.sas_entity_hierarchy_id =3 AND game_deactived.master_agent_id = :masterAgentId ) OR 	(game_deactived.sas_entity_hierarchy_id =4 AND game_deactived.agent_id = :agentId ) )    AND  game_deactived.is_deleted = 0    group by game_deactived.vendor_game_id ) AND vgc.status = :status AND vgcurrency.status = :status AND vgc.vendor_id = :vendorId AND vgcurrency.currency_id IN (:currencyIds) AND vg.game_category_id IN (:categoryIds) GROUP BY  vg.id ORDER BY vg.code, l.code,  p.code) AS gamelist LEFT JOIN ( SELECT vgcl.name as langName, vgcl.image_square as langImageSquare, vgcl.image_landscape as langImageLandscape, vgcl.vendor_game_id FROM vendor_game_codes vgcl  WHERE vgcl.vendor_id =:vendorId AND vgcl.language_id =:languageId GROUP BY vgcl.vendor_game_id, vgcl.name ) AS languageList ON languageList.vendor_game_id = gamelist.gameID
